/**
 * Polylines for `text`, scaled so the letters' outer height (including the stroke) is `height`,
 * with the baseline of the strokes' outer edge at y = 0 and the first letter's left edge at x = 0.
 */
export function textPolylines(text, height, stroke, spacing = 1.6) {
    const s = (height - stroke) / 6;
    if (!(s > 0))
        throw new Error(`text: stroke ${stroke} must be smaller than the letter height ${height}.`);
    const lines = [];
    let x = 0;
    const adv = 4 * s + spacing * s + stroke;
    for (const ch of text.toUpperCase()) {
        const g = GLYPHS[ch];
        if (!g)
            throw new Error(`text: no glyph for "${ch}". Available: ${Object.keys(GLYPHS).join("")}`);
        for (const pl of g)
            lines.push(pl.map(([gx, gy]) => [x + stroke / 2 + gx * s, stroke / 2 + gy * s]));
        x += adv;
    }
    const width = text.length ? x - spacing * s : 0;
    return { lines, width };
}
